  ['*', { type: 'op', op: '*' }],
  ['×', { type: 'op', op: '*' }],
  ['/', { type: 'op', op: '/' }],
  ['÷', { type: 'op', op: '/' }],
  ['^', { type: 'op', op: '^' }],
  ['!', { type: 'postfix', op: '!' }],
  ['%', { type: 'postfix', op: '%' }],
  ['(', { type: 'lparen' }],
